def r1_fleet(now):
    nodes = fleet(now, cpu=65, gpu=52, board=64, load=60, power=100)
    for node in nodes:
        rows = [r for r in R1_PAYLOAD['anchors'] if r['source'][0] == node['host']]
        node.update(hostname=rows[0]['source'][1], power_source=rows[0]['source'][2])
        node['sensors'] = [dict(id=r['source'][3], group=r['source'][4], calibrated=True,
            temp=65 if r['source'][4] in ('cpu', 'acpi') else 52 if r['source'][4] == 'gpu' else 64)
            for r in rows]
    return nodes


class PendingBootTests(unittest.TestCase):
    def test_all_pending_boot_and_restart_use_physical_endpoint_not_old_target_match(self):
        self.assertEqual(len(R1_PAYLOAD['anchors']), 88)
        self.assertEqual(R1_PAYLOAD['intent'], dict(from_level=10, to_level=16, purpose='reserve', state='invalidated'))
        for restored in (False, True):
            for actual in (16, 15):
                with self.subTest(restored=restored, actual=actual):
                    c = Controller(HOSTS, rules_only=True, high_wind_gate=True)
                    if restored:
                        c.restore_thermal_memory(deepcopy(R1_PAYLOAD), 100)
                    before = c.export_thermal_memory()
                    self.assertIsNone(c.operating.confirmed_level)
                    for now in (100, 103, 106, 109):
                        pending = feedback(now, actual, confirmed=False, execution='pending')
                        d = c.decide(r1_fleet(now), now, minimum_level=0, feedback=pending)
                        self.assertEqual(d['level'], actual - 1)
                        self.assertIsInstance(c.high_wind.proof, NoAscent)
                        self.assertEqual(d['execution_trial']['original_deadline'], 160)
                        self.assertEqual(d['execution_trial']['purpose'], 'ceiling_exit')
                        self.assertIsNone(c._policy['operation']['confirmed_at'])
                        self.assertFalse(pending['confirmed'])
                        after = c.export_thermal_memory()
                        for field in ('anchors', 'failures', 'open_edge'):
                            self.assertEqual(after[field], before[field])


class PendingBootServiceTests(service_fixture.HighExitServiceTests):
    async def test_pending_only_boot_replaces_invalidated_r1_intent_durably_before_adjacent_write(self):
        for actual in (16, 15):
            with self.subTest(actual=actual):
                self.controller = Controller(HOSTS, rules_only=True, high_wind_gate=True)
                self.state['controller'] = self.controller
                self.controller.restore_thermal_memory(deepcopy(R1_PAYLOAD), 100)
                self.state['motor_schedule'] = service.MotorSchedule()
                self.now = 100
                d = self.controller.decide(r1_fleet(self.now), self.now, minimum_level=0,
                    feedback=feedback(self.now, actual, confirmed=False, execution='pending'))
                self.state.update(decision=d, fan=matched_fan(actual, self.now, 1100),
                    last_poll=self.now, last_fan=self.now, fan_request=service.FanRequest(
                        d['level'], high_wind=self.controller.high_wind, motion=self.controller.motion))
                self.state['fan'].update(confirmed=False, execution='pending')
                self.memory.invalidate()
                device = FakeFan(['on', 'favorite', actual, 2096])
                await self.apply(device)
                self.assertEqual(device.writes, [])
                await self.memory.flush(self.controller)
                saved = self.memory.store.load()
                self.assertEqual(saved['anchors'], R1_PAYLOAD['anchors'])
                self.assertEqual(saved['failures'], [])
                self.assertIsNone(saved['open_edge'])
                self.assertEqual(saved['intent'], dict(from_level=actual, to_level=actual - 1,
                    purpose='ceiling_exit', state='pending'))
                await self.apply(device)
                self.assertEqual(device.writes, [actual - 1])
                self.assertIsNone(self.controller._policy['operation']['confirmed_at'])
